import json,hashlib
from pathlib import Path
from datetime import datetime,timezone
root=Path.cwd();art=root/'artifacts'/'experiment';new=json.loads((art/'live-contract-v2.json').read_text());new['id']='implicit-influence-live-v3';new['schemaVersion']='afterlight.experiment.contract.live.v3';new['parentLiveContract']='implicit-influence-live-v2';new['frozenAt']=datetime.now(timezone.utc).isoformat();new['settings']['maxProviderPricePerMillion']={'prompt':0.35,'completion':0.95};new['settings']['maxPerRequestPriceUsd']=0;new['adapterSha256']=hashlib.sha256((root/'backend/src/scientific.ts').read_bytes()).hexdigest();new['operationalChange']+=' This final live version additionally enforces the advertised price ceilings in provider routing before dispatch.'
text=json.dumps(new,ensure_ascii=False,sort_keys=True,separators=(',',':'));hash=hashlib.sha256(text.encode()).hexdigest();(art/'live-contract-v3.json').write_text(text+'\n',encoding='utf8');(art/'live-contract-v3-manifest.json').write_text(json.dumps({'id':new['id'],'hash':hash,'hashMethod':'SHA256 of compact, sorted-key JSON without trailing newline','frozenAt':new['frozenAt'],'totalTrials':20,'maxCalls':40},indent=2)+'\n',encoding='utf8')
q=lambda x:"'"+str(x).replace("'","''")+"'"
sql='INSERT INTO contracts (id,version,hash,question_id,name,status,contract_json,created_at) VALUES ('+','.join([q(new['id']),'1',q(hash),q(new['questionId']),q(new['name']),q('validated'),q(text),q(new['frozenAt'])])+') ON CONFLICT(id,version) DO NOTHING;\n'
(root/'backend/work/live-contract-v3-import.sql').write_text(sql,encoding='utf8');print(json.dumps({'id':new['id'],'hash':hash,'route':new['route']}))
